package com.crm.fees;
import com.crm.fees.service.FeeReferenceDirectory;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.cloud.client.discovery.DiscoveryClient;import org.springframework.cloud.client.DefaultServiceInstance;import org.springframework.web.server.ResponseStatusException;import org.junit.jupiter.api.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class FeeReferenceDirectoryTest {
 DiscoveryClient discovery=mock(DiscoveryClient.class);FeeReferenceDirectory directory=spy(new FeeReferenceDirectory(discovery));ObjectMapper json=new ObjectMapper();
 @Test void canonicalReferenceAndBearerAreRequiredBeforeAnyRemoteRead(){for(String id:Arrays.asList(null,"","0","01","EMP-1","-1","1.0","9223372036854775808"))assertThrows(IllegalArgumentException.class,()->directory.require("employee-service","/api/employees/",id,"Bearer synthetic"));assertEquals(401,assertThrows(ResponseStatusException.class,()->directory.validate("1",null,null)).getStatusCode().value());verify(directory,never()).read(any(),any(),any());}
 @Test void remoteIdentifierMustBeExactIntegralObject()throws Exception{for(String body:List.of("null","[]","1","{\"id\":\"1\"}","{\"id\":1.0}","{\"id\":2}","{\"id\":9223372036854775808}")){doReturn(json.readTree(body)).when(directory).read(any(),any(),any());assertEquals(502,assertThrows(ResponseStatusException.class,()->directory.validate("1",null,"Bearer synthetic")).getStatusCode().value());}doReturn(json.readTree("{\"id\":1}")).when(directory).read(any(),any(),any());directory.validate("1",null,"Bearer synthetic");}
 @Test void employeeAndOptionalCustomerUseSeparateNamespaces()throws Exception{doReturn(json.readTree("{\"id\":1}")).when(directory).read("employee-service","/api/employees/1","Bearer synthetic");doReturn(json.readTree("{\"id\":2}")).when(directory).read("customer-service","/api/customers/2","Bearer synthetic");directory.validate("1","2","Bearer synthetic");verify(directory).read("employee-service","/api/employees/1","Bearer synthetic");verify(directory).read("customer-service","/api/customers/2","Bearer synthetic");}
 @Test void absentDiscoveryFailsClosed(){when(discovery.getInstances("employee-service")).thenReturn(List.of());assertEquals(503,assertThrows(ResponseStatusException.class,()->directory.validate("1",null,"Bearer synthetic")).getStatusCode().value());}
 @Test void syntheticHttpChecksBearerAndSanitizedStatusMapping()throws Exception{var seen=new AtomicReference<String>();var status=new java.util.concurrent.atomic.AtomicInteger(200);var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/api/employees/1",r->{seen.set(r.getRequestHeaders().getFirst("Authorization"));int code=status.get();byte[] body=(code==200?"{\"id\":1}":"synthetic private error").getBytes(java.nio.charset.StandardCharsets.UTF_8);r.getResponseHeaders().set("Content-Type","application/json");r.sendResponseHeaders(code,body.length);r.getResponseBody().write(body);r.close();});server.start();try{when(discovery.getInstances("employee-service")).thenReturn(List.of(new DefaultServiceInstance("synthetic","employee-service","127.0.0.1",server.getAddress().getPort(),false)));directory.validate("1",null,"Bearer synthetic");assertEquals("Bearer synthetic",seen.get());for(int code:List.of(301,401,403,404,422,500,503)){status.set(code);var e=assertThrows(ResponseStatusException.class,()->directory.validate("1",null,"Bearer synthetic"));assertEquals(code==301||code>=500?503:code==422?502:code,e.getStatusCode().value());assertFalse(e.getMessage().contains("private"));}}finally{server.stop(0);}}
}
